cd /workspace && python3 -c "
import json, re
# Re-score val_generations 60 with the GRADER rule: last number in full response == gold numerically
def last_number(s):
    nums = re.findall(r'-?[0-9]+\.?[0-9]*', s)
    for n in reversed(nums):
        if n not in ('', '.', '-', '-.'):
            return n
    return None

def normal(n):
    if n is None: return None
    n = n.replace(',', '')
    try:
        return float(n)
    except:
        return n

agree = 0; total = 0; mismatches = 0
mismatch_examples = []
with open('results/run60/val_generations/60.jsonl') as f:
    for line in f:
        d = json.loads(line)
        total += 1
        intern = d['score']
        last = last_number(d['output'])
        grad = 1.0 if normal(last) == normal(d['gts']) else 0.0
        if grad == 1.0: agree += 1
        if abs(intern - grad) > 1e-9:
            mismatches += 1
            if len(mismatch_examples) < 10:
                mismatch_examples.append((d['gts'], last, normal(last), intern))

print(f'Grader-rule accuracy: {agree}/{total} = {agree/total:.4f}')
print(f'Internal score mismatches vs grader: {mismatches}')
for m in mismatch_examples:
    print(m)
"

